51		 *                                                                         has no
52		 *                                                                         transaction
53		 *                                                                         open
54		 * @throws IllegalStateException if the policy requires no Checks at all, which would
55		 *                               write no rows and leave the caller committing the stuck
56		 *                               Transfer described above
57		 */
58		@Transactional(propagation = Propagation.MANDATORY)
59		public void openFor(Transfer transfer) {
60			Long transferId = Objects.requireNonNull(transfer.getId(), "a ledger belongs to a written transfer");
