27	
28		private static final long SOURCE = 1L;
29		private static final long DESTINATION = 2L;
30		private static final long OPENING_BALANCE = 250_00L;
31	
32		@BeforeEach
33		void openBothAccounts() {
34			openAccount(SOURCE, OPENING_BALANCE, EUR);
35			openAccount(DESTINATION, 0L, EUR);
36		}
37	
38		@Test
39		@DisplayName("reserving raises the source Account's Reserved Amount and moves no money")
40		void raisesTheReservedAmountAndMovesNoMoney() {
41			Transfer requested = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));
42	
43			assertThat(requested.getId()).isNotNull();
44			assertThat(requested.getStatus()).isEqualTo(TransferStatus.PENDING);
45	
46			assertThat(balanceOf(SOURCE)).isEqualTo(OPENING_BALANCE);
47			assertThat(reservedAmountOf(SOURCE)).isEqualTo(80_00L);
48			assertThat(availableBalanceOf(SOURCE)).isEqualTo(170_00L);
49	
50			assertThat(balanceOf(DESTINATION)).isZero();
51			assertThat(reservedAmountOf(DESTINATION)).isZero();
52		}
53	
54		/**
55		 * A same-Currency Transfer carries the same figure twice, denominated by the source
56		 * Account rather than by anything the caller said: {@link ReservationRequest} has only a
57		 * count of Minor Units to offer.
58		 */
59		@Test
60		@DisplayName("the PENDING Transfer records both amounts in the Accounts' Currency")
61		void recordsThePendingTransferInTheAccountsCurrency() {
62			reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));
63	
64			assertThat(transferRows()).singleElement().satisfies(row -> assertThat(row)
65					.containsEntry("STATUS", "PENDING")
66					.containsEntry("SOURCE_ACCOUNT_ID", SOURCE)
67					.containsEntry("DESTINATION_ACCOUNT_ID", DESTINATION)
68					.containsEntry("DEBITED_AMOUNT_MINOR_UNITS", 80_00L)
69					.containsEntry("DEBITED_AMOUNT_CURRENCY", "EUR")
70					.containsEntry("CREDITED_AMOUNT_MINOR_UNITS", 80_00L)
