1	package hu.bankmonitor.payments.accounts;
2	
3	import hu.bankmonitor.payments.common.Money;
4	
5	/**
6	 * Raised when a Transfer asks an Account to reserve more than its Available Balance.
7	 *
8	 * <p>Carries both figures because the useful answer to "why was this refused" is the two
9	 * amounts that were compared, and neither is recoverable from the Account afterwards — by
10	 * the time a caller reads it the transaction that refused has rolled back. It carries no
11	 * Account ID, unlike {@link UnknownAccountException}: a Transfer has two Accounts but only
12	 * one it debits, so there is nothing to disambiguate.
13	 *
14	 * <p>Whether the client is told {@code 409} or {@code 422}, and under which problem type
15	 * URN, belongs to the endpoint in ticket 14.
16	 */
17	public class InsufficientFundsException extends RuntimeException {
18	
19		private final Money availableBalance;
20	
21		private final Money requestedAmount;
22	
23		public InsufficientFundsException(Money availableBalance, Money requestedAmount) {
24			super("available balance %s does not cover %s".formatted(availableBalance, requestedAmount));
25			this.availableBalance = availableBalance;
