1	package hu.bankmonitor.payments.transfers;
2	
3	import hu.bankmonitor.payments.accounts.Account;
4	import hu.bankmonitor.payments.common.Currency;
5	import hu.bankmonitor.payments.common.Money;
6	import org.junit.jupiter.api.BeforeEach;
7	import org.junit.jupiter.api.DisplayName;
8	import org.junit.jupiter.api.Test;
9	import org.junit.jupiter.params.ParameterizedTest;
10	import org.junit.jupiter.params.provider.EnumSource;
11	import org.springframework.beans.factory.annotation.Autowired;
12	import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
13	import org.springframework.boot.jpa.test.autoconfigure.TestEntityManager;
14	import org.springframework.test.context.TestPropertySource;
15	
16	import java.time.Instant;
17	import java.util.List;
18	
19	import static org.assertj.core.api.Assertions.assertThat;
20	import static org.assertj.core.api.Assertions.assertThatThrownBy;
21	
22	/**
23	 * A {@link Transfer} survives the trip to the database and back in each of its four
24	 * statuses, keeping its two amounts in the two currencies they are denominated in.
25	 *
26	 * <p>The status is the reason for the round trip: stored by name it is readable in the
27	 * table and stable against a reordering of the enum, and left unannotated JPA would store
28	 * an ordinal instead — silently, and correctly enough to pass a test that only ever wrote
29	 * and read through the same mapping. So each case asserts the string that reached the
30	 * column as well as the value that came back.
31	 *
32	 * <p>Startup is half of every assertion below: {@code validate} has already compared the
33	 * entity against {@code V2__transfers.sql} by the time any method runs.
34	 */
35	@DataJpaTest
36	@TestPropertySource(properties =
37			// The application's own setting, restated because the claim above rests on it.
38			"spring.jpa.hibernate.ddl-auto=validate")
39	class TransferRoundTripsInEveryStatusTest {
40	
41		private static final Instant REQUESTED_AT = Instant.parse("2026-09-05T10:15:30Z");
42	
43		@Autowired
44		private TestEntityManager entityManager;
45	
46		@Autowired
47		private TransferRepository transfers;
48	
49		private Long sourceAccountId;
50		private Long destinationAccountId;
51	
52		@BeforeEach
53		void openTwoAccounts() {
54			sourceAccountId = openAccount(new Money(500_00L, Currency.EUR));
55			destinationAccountId = openAccount(new Money(0L, Currency.HUF));
56		}
57	
58		@Test
59		@DisplayName("a requested Transfer is PENDING from the moment it was requested")
60		void isPendingFromTheMomentItWasRequested() {
61			Long id = transfers.save(pendingTransfer()).getId();
62			entityManager.flush();
63			entityManager.clear();
64	
65			Transfer reopened = transfers.findById(id).orElseThrow();
66	
67			assertThat(reopened.getStatus()).isEqualTo(TransferStatus.PENDING);
68			assertThat(reopened.getSourceAccountId()).isEqualTo(sourceAccountId);
69			assertThat(reopened.getDestinationAccountId()).isEqualTo(destinationAccountId);
70			assertThat(reopened.getCreatedAt()).isEqualTo(REQUESTED_AT);
71		}
72	
73		/**
74		 * The transitions themselves belong to tickets 13, 20 and 23, so the status is moved
75		 * here by a bulk update — which still binds the enum through the entity's own mapping,
76		 * and so exercises the direction a native {@code INSERT} of the string would skip.
77		 */
78		@ParameterizedTest
79		@EnumSource(TransferStatus.class)
80		@DisplayName("a Transfer round-trips in each of its statuses, stored by name")
81		void roundTripsInEachStatus(TransferStatus status) {
82			Long id = transfers.save(pendingTransfer()).getId();
83	
84			advanceTo(id, status);
85			entityManager.clear();
86	
87			Transfer reopened = transfers.findById(id).orElseThrow();
88			assertThat(reopened.getStatus()).isEqualTo(status);
89			assertThat(entityManager.getEntityManager()
90					.createNativeQuery("SELECT status FROM transfers")
91					.getSingleResult()).hasToString(status.name());
92		}
93	
94		/**
95		 * Read in SQL rather than through Hibernate, so this asserts what is in the database
96		 * rather than what the mapping is willing to say about it — a round trip through the
97		 * same mapping would agree with itself whichever columns it chose.
98		 */
99		@Test
100		@DisplayName("the debited and the credited amount each get their own pair of columns")
101		void keepsTheTwoAmountsInColumnsOfTheirOwn() {
102			transfers.save(pendingTransfer());
103			entityManager.flush();
104			entityManager.clear();
105	
106			@SuppressWarnings("unchecked")
107			List<Object[]> rows = entityManager.getEntityManager().createNativeQuery("""
108					SELECT debited_amount_minor_units, debited_amount_currency,
109					       credited_amount_minor_units, credited_amount_currency
110					FROM transfers
111					""").getResultList();
112	
113			assertThat(rows).hasSize(1);
114			assertThat(((Number) rows.getFirst()[0]).longValue()).isEqualTo(120_00L);
115			assertThat(rows.getFirst()[1]).hasToString("EUR");
116			assertThat(((Number) rows.getFirst()[2]).longValue()).isEqualTo(46_800L);
117			assertThat(rows.getFirst()[3]).hasToString("HUF");
118		}
119	
120		@Test
121		@DisplayName("the table refuses a status the domain has no name for")
122		void refusesAStatusTheDomainHasNoNameFor() {
123			assertThatThrownBy(() -> insertTransfer(sourceAccountId, destinationAccountId, 120_00L, "VOIDED"))
124					.hasStackTraceContaining("TRANSFERS_STATUS_IS_KNOWN");
125		}
126	
127		/** The backstop under ticket 14's self-transfer check, not a replacement for it. */
128		@Test
129		@DisplayName("the table refuses a Transfer from an Account to itself")
130		void refusesATransferFromAnAccountToItself() {
131			assertThatThrownBy(() -> insertTransfer(sourceAccountId, sourceAccountId, 120_00L, "PENDING"))
132					.hasStackTraceContaining("TRANSFERS_TWO_DISTINCT_ACCOUNTS");
133		}
134	
135		/** No Transfer may debit the source and credit nothing — design decision 16, via ticket 07. */
136		@Test
137		@DisplayName("the table refuses a Transfer that would move nothing")
138		void refusesATransferThatWouldMoveNothing() {
139			assertThatThrownBy(() -> insertTransfer(sourceAccountId, destinationAccountId, 0L, "PENDING"))
140					.hasStackTraceContaining("TRANSFERS_POSITIVE_AMOUNTS");
141		}
142	
143		@Test
144		@DisplayName("the table refuses a Transfer against an Account that does not exist")
145		void refusesATransferAgainstAnAccountThatDoesNotExist() {
146			assertThatThrownBy(() -> insertTransfer(sourceAccountId, 4_242L, 120_00L, "PENDING"))
147					.hasStackTraceContaining("TRANSFERS_DESTINATION_ACCOUNT");
148		}
149	
150		private Transfer pendingTransfer() {
151			return new Transfer(sourceAccountId, destinationAccountId,
152					new Money(120_00L, Currency.EUR), new Money(46_800L, Currency.HUF), REQUESTED_AT);
153		}
154	
155		private Long openAccount(Money openingBalance) {
156			return entityManager.persistAndGetId(new Account(openingBalance), Long.class);
157		}
158	
159		private void advanceTo(Long id, TransferStatus status) {
160			entityManager.getEntityManager()
161					.createQuery("UPDATE Transfer t SET t.status = :status WHERE t.id = :id")
162					.setParameter("status", status)
163					.setParameter("id", id)
164					.executeUpdate();
165		}
166	
167		private void insertTransfer(Long sourceId, Long destinationId, long minorUnits, String status) {
168			entityManager.getEntityManager().createNativeQuery("""
169							INSERT INTO transfers (source_account_id, destination_account_id,
170							                       debited_amount_minor_units, debited_amount_currency,
171							                       credited_amount_minor_units, credited_amount_currency,
172							                       status, created_at)
173							VALUES (?, ?, ?, 'EUR', ?, 'HUF', ?, ?)
174							""")
175					.setParameter(1, sourceId)
176					.setParameter(2, destinationId)
177					.setParameter(3, minorUnits)
178					.setParameter(4, minorUnits)
179					.setParameter(5, status)
180					.setParameter(6, REQUESTED_AT)
181					.executeUpdate();
182		}
